for cid, obj in P.items():
    with open(os.path.join(BASE, cid + ".json"), "w", encoding="utf-8") as f:
        json.dump(obj, f, ensure_ascii=False, indent=1)
# verify by exact per-id open only
ok = 0
for cid in B23 + B24:
    with open(os.path.join(BASE, cid + ".json"), encoding="utf-8") as f:
        o = json.load(f)
    assert o["case_id"] == cid and set(o.keys()) == {"case_id","prediction_text","basis","confidence","trigger"}
    assert set(o["trigger"].keys()) == {"changed_main","reserve_used","disputed","reason"}
    ok += 1
cm = sum(1 for o in P.values() if o["trigger"]["changed_main"])
ru = sum(1 for o in P.values() if o["trigger"]["reserve_used"])
di = sum(1 for o in P.values() if o["trigger"]["disputed"])
print("written", ok, "changed_main", cm, "reserve_used", ru, "disputed", di)
